<?php $fs=["templates/etablissement/edit.html.twig","templates/etablissement/new.html.twig"]; foreach($fs as $f){ if(!file_exists($f)) continue; $c=file_get_contents($f); $c=preg_replace("/<div class=\"panel-section\">\s*<div class=\"section-title\">Localisation carte<\/div>.*?(?=<div class=\"panel-section\">)/is","", $c); $c=preg_replace("/\s*\x27latitude\x27: form.latitude.vars.id,/", "", $c); $c=preg_replace("/\s*\x27longitude\x27: form.longitude.vars.id,/", "", $c); file_put_contents($f, $c); echo "Done $f\n"; } $s="templates/etablissement/_form_scripts.html.twig"; if(file_exists($s)){ $c=file_get_contents($s); $c=preg_replace("/function initMap\(\) \{.*?\}/is", "function initMap() {}", $c); file_put_contents($s, $c); echo "Done $s\n"; }
